s.groups.forEach(g => g.items.forEach(i => { i.id = g.id + '|' + i.code; i.price = 0 }))
s.searchText = ''
s.activeGroup = 'all'
s.selected = {}

s.query = () => (s.searchText || '').trim().toLowerCase()
s.filteredItems = g => {
 const q=s.query()
 if(!q) return g.items
 const groupHit=(g.code+' '+g.name).toLowerCase().includes(q)
 return groupHit ? g.items : g.items.filter(i => (i.code+' '+i.name).toLowerCase().includes(q))
}
s.visibleGroups = () => s.groups.filter(g => {
 if(s.activeGroup!=='all' && g.id!==s.activeGroup) return false
 if(!s.query()) return true
 return (g.code+' '+g.name).toLowerCase().includes(s.query()) || s.filteredItems(g).length>0
})
s.setGroupFilter = id => { s.activeGroup=id }
s.onSearchInput = value => { s.searchText=value||'' }
s.isItemChecked = item => !!s.selected[item.id]
s.selectedInGroup = g => g.items.filter(i => s.isItemChecked(i)).length
s.isGroupChecked = g => {
 const items=s.filteredItems(g)
 return items.length>0 && items.every(i => s.isItemChecked(i))
}
s.isGroupIndeterminate = g => {
 const items=s.filteredItems(g)
 const count=items.filter(i => s.isItemChecked(i)).length
 return count>0 && count<items.length
}
s.toggleGroup = g => {
 const items=s.filteredItems(g)
 const uncheck=items.length>0 && items.every(i => s.isItemChecked(i))
 items.forEach(i => {
  if(uncheck) delete s.selected[i.id]
  else s.selected[i.id]={...i,groupId:g.id,groupName:g.name}
 })
 s.sync()
}
s.toggleItem = (item,g) => {
 if(s.selected[item.id]) delete s.selected[item.id]
 else s.selected[item.id]={...item,groupId:g.id,groupName:g.name}
 s.sync()
}
s.selectedList = () => Object.values(s.selected)
s.selectedCount = () => s.selectedList().length
s.selectedTotal = () => s.selectedList().reduce((sum,i)=>sum+(Number(i.price)||0),0)
s.money = value => Number(value||0).toLocaleString('th-TH',{minimumFractionDigits:2,maximumFractionDigits:2})
s.removeSelected = id => { delete s.selected[id]; s.sync() }
s.clearSelected = () => { s.selected={}; s.sync() }
s.sync = () => {
 const f=field.getFormRef()
 if(f) f.setFieldValue('selected_items_json',JSON.stringify(s.selectedList()))
}

