.lab-patient-card {
  border: 1px solid var(--el-border-color);
  border-radius: 12px;
  background: var(--el-bg-color);
}

.lab-patient-card .el-card__body {
  padding: 16px 18px;
}

.lab-patient-main {
  display: flex;
  align-items: center;
  gap: 16px;
  min-width: 0;
}

.lab-patient-avatar {
  flex: none;
  background: var(--el-fill-color-light);
  border: 1px solid var(--el-border-color);
}

.lab-patient-avatar-placeholder {
  width: 62%;
  height: 62%;
  fill: var(--el-text-color-secondary);
}

.lab-patient-identity {
  flex: 1;
  min-width: 0;
}

.lab-patient-name-row {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 7px;
}

.lab-patient-name {
  margin-right: 3px;
  color: var(--el-text-color-primary);
  font-size: 20px;
  font-weight: 750;
}

.lab-patient-meta {
  margin-top: 8px;
  color: var(--el-text-color-regular);
  font-size: 13px;
}

.lab-patient-sep {
  margin: 0 8px;
  color: var(--el-text-color-placeholder);
}

.lab-patient-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 9px;
}

.lab-patient-chip {
  display: inline-flex;
  align-items: center;
  padding: 2px 9px;
  border: 1px solid var(--el-border-color-lighter);
  border-radius: 999px;
  color: var(--el-text-color-regular);
  background: var(--el-fill-color-light);
  font-size: 12px;
  font-weight: 600;
}

.lab-patient-chip.primary {
  color: var(--el-color-primary);
  background: var(--el-color-primary-light-9);
  border-color: var(--el-color-primary-light-8);
}

.lab-patient-chip.warning {
  color: var(--el-color-warning);
  background: var(--el-color-warning-light-9);
  border-color: var(--el-color-warning-light-8);
}

.lab-patient-chip.success {
  color: var(--el-color-success);
  background: var(--el-color-success-light-9);
  border-color: var(--el-color-success-light-8);
}

.lab-patient-chip.danger {
  color: var(--el-color-danger);
  background: var(--el-color-danger-light-9);
  border-color: var(--el-color-danger-light-8);
}

@media (max-width: 700px) {
  .lab-patient-main {
    align-items: flex-start;
  }

  .lab-patient-avatar {
    width: 58px !important;
    height: 58px !important;
  }

  .lab-patient-name {
    font-size: 17px;
  }

  .lab-patient-meta {
    line-height: 1.8;
  }

  .lab-patient-sep {
    display: none;
  }
}

formConfig.onFormDataChange:
if (fieldName !== 'selected_items_json') return
const hasItems = newValue && newValue !== '[]' && newValue !== 'null'
if (hasItems) return
const w = this.getFieldRef('lab_che_order_ui')
if (w && w.vueState && Object.keys(w.vueState.selected || {}).length) w.vueState.selected = {}
